-- The nightly retention run has a second audit action: `retention.reported`, for a run that only counted what it would
-- have changed (a production run while a period it applies is a proposal; spec 0007b R4). `retention.ran` stays for a run
-- that changed rows, so the log never says that a run happened which only counted.
ALTER TABLE "audit_log" DROP CONSTRAINT "audit_log_action", ADD CONSTRAINT "audit_log_action" CHECK ("action" in ('department.created', 'department.updated', 'fieldOfStudy.created', 'fieldOfStudy.updated', 'socialEvent.created', 'publicFile.registered', 'person.registered', 'person.profileUpdated', 'account.invited', 'account.activated', 'account.deactivated', 'account.reactivated', 'account.passwordReset', 'team.created', 'team.updated', 'team.deactivated', 'membership.added', 'membership.extended', 'membership.changed', 'membership.endedEarly', 'membership.cancelled', 'adminGrant.granted', 'adminGrant.revoked', 'endingSoon.sent', 'consent.given', 'consent.withdrawn', 'person.exported', 'person.erased', 'person.merged', 'person.photoSet', 'person.photoRemoved', 'alumni.requested', 'retention.ran', 'retention.reported'));